class BowlingGame:
    def __init__(self):
        self.rolls = []
        self.frames = []
        self.current = []
        self.game_over = False

    def roll(self, pins):
        if self.game_over:
            raise Exception("Cannot roll after the game is over")
        if not 0 <= pins <= 10:
            raise Exception("A roll must knock down between 0 and 10 pins")

        if len(self.frames) < 9:
            if len(self.current) == 1 and self.current[0] + pins > 10:
                raise Exception(
                    "Two rolls in a frame cannot knock down more than 10 pins"
                )
        else:
            # Tenth frame: validate bonus rolls
            if len(self.current) == 1:
                if self.current[0] != 10 and self.current[0] + pins > 10:
                    raise Exception(
                        "Two rolls in a frame cannot knock down more than 10 pins"
                    )
            elif len(self.current) == 2:
                if self.current[0] == 10 and self.current[1] != 10:
                    if self.current[1] + pins > 10:
                        raise Exception(
                            "Bonus rolls after a strike cannot knock down more than 10 pins"
                        )

        self.rolls.append(pins)
        self.current.append(pins)
        self._maybe_close_frame()

    def _maybe_close_frame(self):
        frame = self.current
        if len(self.frames) < 9:
            if frame[0] == 10 or len(frame) == 2:
                self._close_frame()
        else:
            if frame[0] == 10:
                if len(frame) == 3:
                    self._close_frame()
            else:
                if len(frame) == 2 and sum(frame) < 10:
                    self._close_frame()
                elif len(frame) == 3:
                    self._close_frame()

    def _close_frame(self):
        self.frames.append(self.current)
        self.current = []
        if len(self.frames) == 10:
            self.game_over = True

    def score(self):
        if not self.game_over:
            raise Exception("Cannot score an incomplete game")

        rolls = self.rolls
        total = 0
        idx = 0
        for frame in range(10):
            if frame < 9:
                if rolls[idx] == 10:
                    total += 10 + rolls[idx + 1] + rolls[idx + 2]
                    idx += 1
                elif rolls[idx] + rolls[idx + 1] == 10:
                    total += 10 + rolls[idx + 2]
                    idx += 2
                else:
                    total += rolls[idx] + rolls[idx + 1]
                    idx += 2
            else:
                total += sum(rolls[idx:])
        return total

